<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class StoreBookingRequest extends FormRequest {public function authorize():bool{return $this->user()!==null;}public function rules():array{return ['event_id'=>['required','integer','exists:events,id'],'items'=>['required','array','min:1'],'items.*.ticket_category_id'=>['required','integer','distinct','exists:ticket_categories,id'],'items.*.quantity'=>['required','integer','min:1','max:20']];}public function messages():array{return ['event_id.required'=>'الفعالية مطلوبة.','items.required'=>'اختر نوع تذكرة واحدًا على الأقل.','items.*.quantity.max'=>'الكمية المطلوبة أكبر من الحد المسموح.'];}}
